<template>
	<view class="pages">
		<view v-if="isAdmin">
			<view class="headerClass">
				<view class="buttonClass" @click="openAdd"> 添加 </view>
				<uni-easyinput v-model="searchStr" prefixIcon="search" confirm-type="search" @confirm="iconClick" @clear="iconClick" placeholder="编号/归属人/名字/手机" @iconClick="iconClick">
				</uni-easyinput>
				<view class="statusClass">
					<uni-data-select @change="iconClick" placeholder="全部状态" :localdata="[
						{
							text: '全部',
							value: '',
						},
						{
							text: '正常',
							value: 1,
						},
						{
							text: '异常',
							value: 2,
						},
						{
							text: '封禁',
							value: 3,
						},
					]" v-model="searchStatus" :clear="false"></uni-data-select>
				</view>
			</view>
			<mescroll-body ref="mescroll" @down="downCallback" @up="upCallback" :up="upObj">
				<view class="contentClass">
					<view ref="table" :loading="loading">
						<view class="table-header">
							<view class="table-item">编号</view>
							<view class="table-item">主体</view>
							<view class="table-item">话务/绑定</view>
							<view class="table-item">业务员</view>
							<view class="table-item">状态</view>
						</view>
						<view v-if="wChatList && wChatList.length > 0">
							<view v-for="(item, index) in wChatList" :key="index" class="table-tbody" @click="openEdit(item)">
								<view class="table-item">
									{{ item.code }}
								</view>
								<view class="table-item">
									{{ item.mainName }}
								</view>
								<view class="table-item">
									{{ item.trafficName }}
								</view>
								<view class="table-item">
									{{ item.salesmanName }}
								</view>
								<view class="table-item">
									<view :style="{
										color:
											item.statusFlag == 1
												? 'green'
												: item.statusFlag == 2
													? 'orange'
													: item.statusFlag == 3
														? 'red'
														: 'gray',
									}">
										{{
											item.statusFlag == 1
												? "正常"
												: item.statusFlag == 2
													? "异常"
													: item.statusFlag == 3
														? "封禁"
														: "--"
										}}
									</view>
								</view>
							</view>
						</view>
						<view v-if="wChatList && wChatList.length == 0" class="none-data">
							<noData />
						</view>
					</view>
					<!-- <uni-pagination v-if="wChatList.length > 0" show-icon :page-size="20" :current="pageNo" :total="total" @change="pageChange" /> -->
				</view>
			</mescroll-body>
		</view>
		<view v-if="!isAdmin">
			<view class="pages">
				<view class="main">
					<view class="text">暂无权限</view>
				</view>
			</view>
		</view>
		<uni-popup ref="editPopup" borderRadius="10px" background-color="#fff" type="dialog">
			<view class="editClass">
				<view class="editHeaderClass">
					<view class="title">
						{{ title }}
					</view>
					<view @click="closeDialog">
						<uni-icons type="closeempty"></uni-icons>
					</view>
				</view>
				<view class="editContentClass">
					<view class="editItemClass">
						<view class="label-title">标签/编码</view>
						<uni-easyinput placeholder="请输入标签/编码" v-model="editData.code"></uni-easyinput>
					</view>
					<view class="editItemClass">
						<view class="label-title">微信名</view>
						<uni-easyinput placeholder="请输入微信名" v-model="editData.userName"></uni-easyinput>
					</view>
					<view class="editItemClass">
						<view class="label-title">所属主体</view>
						<uni-data-select :localdata="mainList" :clear="false" v-model="editData.mainId"></uni-data-select>
					</view>
					<view class="editItemClass">
						<view class="label-title">业务员</view>
						<uni-data-select :localdata="salesmanList" :clear="false" v-model="editData.salesmanId"></uni-data-select>
					</view>
					<view class="editItemClass">
						<view class="label-title">状态</view>
						<uni-data-select :clear="false" :localdata="[
							{
								text: '正常',
								value: 1,
							},
							{
								text: '异常',
								value: 2,
							},
							{
								text: '封禁',
								value: 3,
							},
						]" v-model="editData.statusFlag"></uni-data-select>
					</view>
					<view class="submit" @click="handleEdit">确 定</view>
				</view>
			</view>
		</uni-popup>
		<tab :id="4"/>
	</view>
</template>

<script>
import {
	getWChatList,
	editWChatInfo,
	getSelectMainList,
	getSelectSalesmanList
} from '@/util/api';
import noData from '../component/noData.vue'
import tab from "../../components/wyg-bottom-tab/wyg-bottom-tab.vue";

export default {
	props: {
		isAdmin: {
			type: Boolean,
			default: false
		}
	},
	components: { noData, tab },
	data() {
		return {
			wChatList: [],
			pageNo: 1,
			total: 0,
			loading: false,
			mainList: [],
			salesmanList: [],
			editData: {
				code: null,
				userName: null,
				mainId: null,
				salesmanId: null,
				statusFlag: null
			},
			searchStr: null,
			searchStatus: null,
			title: '',
			upObj: { num: this.pageNo, size: 10, textNoMore: '-到底啦-'}
		}
	},
	methods: {
		async downCallback(mescroll) {
			this.pageNo = 1
			this.wChatList = []
			await this.getWChatDataList(mescroll)
			await this.initMainList()
			await this.initSalesmanList()
			if (this.total == this.wChatList.length) {
				mescroll.endSuccess(this.total, false)
			} else {
				mescroll.endSuccess(this.wChatList.length, true)
			}
			mescroll.resetUpScroll( false )
		},
		upCallback(mescroll) {
			this.pageNo += 1
			if (this.total == this.wChatList.length) {
				mescroll.endSuccess()
			} else {
				this.getWChatDataList(mescroll)
			}
			console.log(mescroll, 'mescroll');
		},
		closeDialog() {
			this.$refs.editPopup.close()
		},
		async initMainList() {
			await getSelectMainList().then(res => {
				this.mainList = res.data
			})
		},
		async initSalesmanList() {
			await getSelectSalesmanList().then(res => {
				this.salesmanList = res.data
			})
		},
		async getWChatDataList(mescroll) {
			this.loading = true
			await getWChatList({
				current: this.pageNo,
				size: 10,
				searchStr: this.searchStr,
				statusFlag: this.searchStatus
			}).then(res => {
				this.wChatList = this.wChatList.concat(res.data.records || [])
				this.total = res.data.total
				this.loading = false
				if (this.total == this.wChatList.length) {
					mescroll.endSuccess(this.total, false)
				}
			})
		},
		openEdit(item) {
			this.title = '编辑微信'
			this.editData = item
			this.$refs.editPopup.open()
		},
		openAdd() {
			this.title = '新增微信'
			this.editData = {
				code: null,
				userName: null,
				mainId: null,
				salesmanId: null,
				statusFlag: null
			}
			this.$refs.editPopup.open()
		},
		iconClick() {
			this.pageNo = 1
			this.getWChatDataList()
		},
		pageChange(pageIndex) {
			this.pageNo = pageIndex.current
			this.wChatList = []
			this.getWChatDataList()
		},
		handleEdit() {
			let that = this
			if (!that.editData.code) {
				return that.hint('标签/编码不能为空')
			}
			if (!that.editData.userName) {
				return that.hint('微信名不能为空')
			}
			if (!that.editData.mainId) {
				return that.hint('请选择主体')
			}
			if (!that.editData.salesmanId) {
				return that.hint('请选择业务员')
			}
			if (!that.editData.statusFlag) {
				return that.hint('请选择状态')
			}
			editWChatInfo(this.editData).then(res => {
				uni.showModal({
					title: '提示',
					content: '操作成功',
					showCancel: false,
					success() {
						that.pageNo = 1
						that.getWChatDataList()
						that.$refs.editPopup.close()
					}
				})
			})
		}
	}
}
</script>

<style lang="scss" scoped>
.main {
	display: flex;
	justify-content: center;
	align-items: center;
	padding: 200rpx;

	.text {
		font-size: 54rpx;
		color: #656565;
	}
}

.headerClass {
	display: flex;
	align-items: center;
	justify-content: space-between;
	padding: 14rpx;

	.buttonClass {
		display: flex;
		align-items: center;
		justify-content: center;
		color: white;
		background-color: #ff0000;
		padding: 15rpx;
		font-size: 28rpx;
		border-radius: 6rpx;
	}

	::v-deep .is-input-border {
		border-radius: 8rpx 0 0 8rpx;
	}

	::v-deep .uni-easyinput__content-input {
		height: 66rpx;
	}

	.statusClass {
		// width: 150rpx;
	}
}

.contentClass {
	.table-header {
		display: flex;
		width: 100%;
		justify-content: space-between;
		background: #e5e5e5;
		color: #656565;
		font-size: 28rpx;
		padding: 14rpx 28rpx;
		box-sizing: border-box;

		.table-item {
			white-space: nowrap;
			text-align: center;

			&:first-child {
				width: 15%;
			}

			&:nth-child(2) {
				width: 35%;
			}

			&:nth-child(3) {
				width: 20%;
			}

			&:nth-child(4) {
				width: 20%;
			}

			&:nth-child(5) {
				width: 10%;
			}
		}
	}

	.none-data {
		font-size: 36rpx;
		color: #656565;
		padding: 200rpx 0 0 0;
		text-align: center;
	}

	.table-tbody {
		display: flex;
		width: 100%;
		justify-content: space-between;
		color: #000;
		font-size: 24rpx;
		padding: 24rpx 28rpx;
		box-sizing: border-box;
		border-bottom: 2rpx solid #ccc;

		.table-item {
			white-space: nowrap;
			text-align: center;

			&:first-child {
				width: 15%;
			}

			&:nth-child(2) {
				width: 35%;
			}

			&:nth-child(3) {
				width: 20%;
			}

			&:nth-child(4) {
				width: 20%;
			}

			&:nth-child(5) {
				width: 10%;
			}
		}
	}
}

.editClass {
	width: 80vw;
	padding: 0 24rpx 24rpx 24rpx;
	border-radius: 12rpx;

	.editHeaderClass {
		display: flex;
		align-items: center;
		justify-content: space-between;
		border-bottom: solid 1rpx #e8e8e8;
		padding: 16rpx 0;

		.title {
			font-size: 32rpx;
		}
	}

	.form-content {
		.form-item {
			margin: 0;
		}
	}

	.submit {
		width: 100%;
		background: #3d8bf2;
		text-align: center;
		color: white;
		font-size: 28rpx;
		padding: 16rpx 0;
		border-radius: 6rpx;
	}

	::v-deep .uni-forms-item {
		margin-bottom: 10rpx;
		border-bottom: 1px solid #eee;

		&:first-child {
			border: none;
		}

		&:nth-child(2) {
			border: none;
		}
	}

	.editContentClass {
		width: 100%;

		.editItemClass {
			display: flex;
			align-items: center;
			justify-content: space-between;
			width: 100%;
			padding: 12rpx 0 12rpx 24rpx;
			color: #333;
			border-bottom: 1px solid #eee;
			position: relative;

			.label-title {
				width: 140rpx;
				font-size: 28rpx;
			}

			&::before {
				content: "*";
				color: red;
				position: absolute;
				left: 0;
			}
		}
	}

	::v-deep .uni-easyinput__content-input {
		height: 66rpx;
		width: 90%;
	}
}

::v-deep .uni-select__selector-item {
	white-space: nowrap;
	font-size: 28rpx;
}
</style>